import json
import sys
from http.server import HTTPServer, BaseHTTPRequestHandler

request_count = 0


class Handler(BaseHTTPRequestHandler):
    def _handle(self, method):
        global request_count
        request_count += 1

        if method == "GET" and self.path == "/health":
            self._respond(200, b"ok")
        elif method == "POST" and self.path == "/echo":
            length = int(self.headers.get("Content-Length", 0))
            body = self.rfile.read(length) if length else b""
            self._respond(200, body)
        elif method == "GET" and self.path == "/count":
            self._respond(200, str(request_count - 1).encode())
        else:
            self._respond(404, json.dumps({"error": "not found"}).encode())

    def _respond(self, code, body):
        self.send_response(code)
        self.send_header("Content-Type", "text/plain" if code != 404 else "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        self._handle("GET")

    def do_POST(self):
        self._handle("POST")


if __name__ == "__main__":
    port = int(sys.argv[1])
    server = HTTPServer(("0.0.0.0", port), Handler)
    print(f"Serving on port {port}")
    server.serve_forever()

